/*
 * Y2002电音 (y2002.com) 原生 Ceru v2 插件
 * 站点：PC API http://pc-api.yy-5.com + 主站 https://www.y2002.com
 * 音质：64k 试听 / 320k(仅 _mp3 原始档) / flac(仅 _wav/_flac 原始档)，如实标注不虚标
 *
 * 实测（2026-11-18）：
 *   搜索: GET pc-api.yy-5.com/api/music/search?key=&pi=&pz=&deviceId=&version= → result.datalist
 *        （songname 常"艺人-标题"、songurl 相对路径 _mp3/_wav/_flac.m4a 标识原始格式、duration 毫秒、
 *          ownerid、headpic 相对路径）
 *   分类: /api/music/tabs → result 数组（12 分类 667-678）；/api/music/ListByTab?tabid=&pi=&pz=&cursor=
 *   推荐: /api/music/RecListOfPc?pi=&pz=&cursor= → result.cursor 翻页（会话内缓存接力）
 *   最新上传: GET www.y2002.com/ 解析 <a href='/Songs/{ownerId}/{id}.html' class='song'>
 *   播放: GET /Songs/{ownerid}/{id}.html → var mu="https://fd-y2-p-p.y2002.com:443/..._o.m4a?sign="
 *        试听 m4a（实测 ftyp isom、Range 206、11MB 级）
 *   下载: songurl 去 _xxx.m4a 换原始扩展名 + DOWNLOAD_HOST fd-y2-p-d.y2002.com，
 *        t=hex(Unix秒+5h)，sign=MD5(DOWNLOAD_KEY+path+t)；实测 wav 档 RIFF 魔数 206 + 245MB
 *   档位: standard=试听 m4a（全曲）；high=原始 mp3（仅 _mp3 源）；super=原始 wav/flac（仅 _wav/_flac）
 *        （实测 2026-10-03：standard 65kbps、high 320kbps、super 原始无损）
 *   无歌词（PC API 无 lrc、App 需签名），恒空
 */
exports.manifest = {
  manifestVersion: 2,
  id: 'ceru.y2002',
  name: 'Y2002电音',
  version: '1.0.0',
  description: '支持音质：64k/320k/flac',
  author: 'hebijunge',
  engines: { hostApi: '^2.0.0', logicRuntime: 'ceru-js@1' },
  modules: { logic: { entry: 'logic.main' } },
  permissions: [{ key: 'network', name: 'network.request', reason: '搜索与取链需要访问网络' }],
  contributes: {
    providers: [{
      id: "ceru.y2002",
      name: 'Y2002电音',
      protocols: ['music.search@1', 'music.resolve@1', 'music.charts@1'],
      qualities: ['64k', '320k', 'flac'],
      connectionMode: 'none'
    }]
  }
};

